import { Component, JSX, onMount, onCleanup, splitProps } from 'solid-js';

export interface StackingCardsProps extends JSX.HTMLAttributes<HTMLDivElement> {
  topStart?: number;
  topIncrement?: number;
  cardGap?: number;
  scaleThreshold?: number;
  minScale?: number;
  reverseScale?: boolean;
}

export const StackingCards: Component<StackingCardsProps> = (props) => {
  let containerRef: HTMLDivElement | undefined;
  const [local, others] = splitProps(props, [
    'topStart',
    'topIncrement',
    'cardGap',
    'scaleThreshold',
    'minScale',
    'reverseScale',
    'class',
    'children',
  ]);

  const topStart = () => local.topStart ?? 20;
  const topIncrement = () => local.topIncrement ?? 28;
  const cardGap = () => local.cardGap ?? 20;
  const reverseScale = () => local.reverseScale ?? true;

  onMount(() => {
    if (!containerRef) return;
    const updateStack = () => {
      if (!containerRef) return;
      const cards = Array.from(containerRef.children) as HTMLElement[];
      const total = cards.length;
      if (total <= 1) return;

      cards.forEach((card, i) => {
        const stickyTop = reverseScale() && i === total - 1 ? topStart() : topStart() + i * topIncrement();
        card.style.position = 'sticky';
        card.style.top = `${stickyTop}px`;
        card.style.zIndex = `${i + 1}`;
        card.style.marginBottom = `${cardGap()}px`;
      });
    };

    updateStack();
    window.addEventListener('scroll', updateStack, { passive: true });
    window.addEventListener('resize', updateStack, { passive: true });

    onCleanup(() => {
      window.removeEventListener('scroll', updateStack);
      window.removeEventListener('resize', updateStack);
    });
  });

  return (
    <div
      ref={containerRef}
      class={`relative flex flex-col w-full max-w-2xl mx-auto ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </div>
  );
};

