import 'package:flutter/material.dart';

class ExhumaStackingCards extends StatelessWidget {
  final List<Widget> children;
  final double topStart;
  final double topIncrement;
  final double cardGap;
  final double scaleThreshold;
  final double minScale;
  final bool reverseScale;

  const ExhumaStackingCards({
    super.key,
    required this.children,
    this.topStart = 20.0,
    this.topIncrement = 28.0,
    this.cardGap = 20.0,
    this.scaleThreshold = 150.0,
    this.minScale = 0.9,
    this.reverseScale = true,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      children: children.asMap().entries.map((entry) {
        final index = entry.key;
        final widget = entry.value;
        return Container(
          margin: EdgeInsets.only(
            top: index == 0 ? topStart : topIncrement,
            bottom: cardGap,
          ),
          child: widget,
        );
      }).toList(),
    );
  }
}

